export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二天早上，王座廳變了樣子。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "王座被推到後牆，蓋上一塊防塵布。大廳正中央擺了一張長桌，桌上兩杯水、一疊空白的評分表、一支筆，還有一塊摺好的紙牌，寫著「面試官」。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "桌子對面，隔著一大片石板地，孤零零放著一張椅子。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)比勇者闖城那天還緊張。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "第一位，聖騎士奧德里克。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "進來的人穿著一整套銀白色鎧甲，擦得很亮，亮到魔王得瞇起眼睛。他在椅子前站定，先鞠了一個角度精準的躬，才坐下。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "您好。這是我的履歷，以及推薦信。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "推薦信有七封。其中三封蓋的是國王的印。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "你屠過龍。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "十一條。兩條是誤會，後來有和解。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "為什麼想應徵這個職位？", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "老實說，我在騎士團已經升到頂了，每天都在開會。我想做一點比較有挑戰性的事。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)他說「挑戰性」的時候看著我，像在看一座還沒爬過的山。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "先確認一下，貴城的工作內容是定期討伐魔王，對嗎？", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "是的。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "那如果我第一次就成功了呢？這樣算試用期通過，還是有遣散費？", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)他是認真的。他真的在問遣散費。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "這部分我們會再研究。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "好的。另外，有勞保嗎？", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "有。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "有嗎？", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "昨天辦的。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "奧德里克點點頭，在一本小冊子上記了一筆。他寫字的姿勢跟握劍一樣，手腕很穩。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)他能贏。不是可能，是能。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)而我要的，不是一個能贏的人。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "我們會再通知你。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "奧德里克", dialogue: "謝謝。期待與您交手。", background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "第二位。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "門開了一條縫，然後被推得更開一點。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "進來的是一個孩子。頭上戴著一頂明顯太大的頭盔，每走一步就往下滑一點，他就每走一步把它推回去一點。背上揹著一把木劍，劍身上用蠟筆寫著「聖劍」。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "我是勇者托比。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "⋯⋯請坐。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "托比爬上椅子，腳碰不到地。他從背包裡拿出一張紙，雙手遞過來。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "這是同意書。我媽媽簽的。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "「本人同意小兒托比參加魔王城宿敵面試。請於五點半前讓他回家吃飯。」簽名下面還有一行小字：「他很認真，請不要嚇他。」", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "你幾歲？", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "九歲半。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "為什麼想當我的宿敵？", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "老師要我們寫「我的志願」。大家都寫麵包師傅跟騎士，我想寫一個沒有人寫過的。而且你看起來很寂寞。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "魔王拿著同意書的手停了一下。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "⋯⋯誰說的。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "公告上寫「能定期來訪」。不寂寞的人不會寫得那麼認真。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)九歲半。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "托比，你有什麼專長嗎？", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "我很會躲貓貓。還有，我每天都可以來，我家就在山下。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他說「每天」的時候很篤定，好像那是一件不需要證明的事。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "你可以在我的聯絡簿上簽名嗎？老師說要家長或主管簽。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "聯絡簿翻開的那一頁，已經工工整整寫好一格：「今日活動：面試魔王。」", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "魔王簽了。他的簽名有三百年的歷史，筆畫繁複，擠在聯絡簿的小格子裡，很勉強。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "托比", dialogue: "謝謝。那我先回去了，等一下要寫數學。", background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他推了推頭盔，走了。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "第三位⋯⋯我先去倉庫拿茶葉。茶快沒了。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "現在？", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "馬上回來。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她從側門出去。大約一分鐘後，正門開了。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "進來的是一位女性。一頭蓬鬆的金色捲髮，一副圓框眼鏡，一件魔王從沒見過的淡紫色洋裝。她在椅子上坐下，背脊挺直，雙手交疊放在膝上。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.MysteriousApplicant, character: "神祕應徵者", dialogue: "您好。我叫琳瑟。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "魔王低頭看她的履歷。字跡工整，每一筆收尾都往右上微微勾起。這個字跡他看了一百一十年，在每一張行程表、每一份請款單、每一份昨天才辦好的勞保文件上。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "金色捲髮的邊緣，露出一小截黑色的頭髮。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)瑟琳。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "⋯⋯請說說妳的經歷。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.MysteriousApplicant, character: "神祕應徵者", dialogue: "我對貴城非常熟悉。我知道第七層的刀陣啟動前會延遲兩秒，知道您的披風左肩有一個補過的洞，也知道您每次講完開場白，都會偷偷喝一口水。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "那些是內部資訊。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.MysteriousApplicant, character: "神祕應徵者", dialogue: "我做了很多功課。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "妳為什麼想當我的宿敵？", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她停了一下。眼鏡後面的眼睛看著他，很平靜，跟每天早上遞行程表的時候一模一樣。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.MysteriousApplicant, character: "神祕應徵者", dialogue: "因為勇者會老，會膝蓋痛，會去種蕪菁。而您需要一個不會走的人。", background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "魔王沒有說話。高窗外有烏鴉飛過，影子從長桌上一閃而過。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)一百一十年。她一次也沒有遲到過。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "⋯⋯我們會再通知妳。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她起身，鞠躬，從正門離開。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "一分鐘後，側門打開。瑟琳抱著一罐茶葉走進來，呼吸有一點急，領口沾著一根金色的頭髮。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "面試還順利嗎？", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "⋯⋯還順利。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "瑟琳", dialogue: "那麼，陛下決定錄取哪一位？", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "桌上攤著三份履歷。一份蓋著國王的印，一份附著家長同意書，一份的字跡，他閉著眼睛都認得。", background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "(內心)總要選一個。月曆還空著。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
];
